CREATE TABLE despachos(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,id_venta BIGINT NOT NULL UNIQUE REFERENCES ventas(id),id_cliente VARCHAR(100),direccion_entrega VARCHAR(255) NOT NULL,transportista VARCHAR(100),estado VARCHAR(20) NOT NULL,fecha_envio TIMESTAMP,fecha_entrega_estimada TIMESTAMP,id_zona BIGINT,id_transportista BIGINT,tarifa NUMERIC(10,2),version BIGINT NOT NULL DEFAULT 0);
